  const norm = (s) => String(s).replace(/\s+/g, " ").trim();
  let lang = "en";
  try { lang = localStorage.getItem("gonka-lang") || "en"; } catch (_) {}

  const lookup = (key) => { const e = T[norm(key)]; return e ? e[lang] || null : null; };
  const sub = (s, vars) => vars ? s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m)) : s;

  return {
    langs: LANGS,
    lang: () => lang,
    set: (l) => { lang = l; try { localStorage.setItem("gonka-lang", l); } catch (_) {} },
    /** Translate; falls back to the (English) key itself. Supports {x} params. */
    t: (key, vars) => sub(lookup(key) || key, vars),
    /** Return a translation only if one exists (used by the DOM auto-translator). */
    maybe: (key) => lookup(key)
  };
